// Page model. Slugs are lowercase, hyphen separated, ASCII; they are part of public URLs.
import { slugify } from "../vendor/slugify/index.ts";

export interface Page {
  title: string;
  slug: string;
  body: string;
}

export function pageSlug(title: string): string {
  return slugify(title, "-");
}

export function makePage(title: string, body: string): Page {
  return { title, slug: pageSlug(title), body };
}
---
import { test } from "node:test";
import assert from "node:assert/strict";
import { makePage, pageSlug } from "../src/pages.ts";

test("release notes page slug", () => {
  assert.equal(pageSlug("release notes 2026"), "release-notes-2026");
});

test("makePage carries the slug", () => {
  assert.equal(makePage("getting started", "...").slug, "getting-started");
});
---
# docsite-pages

Page model for the documentation site. `pageSlug(title)` turns a page title into the URL segment; slugs are lowercase, hyphen separated and ASCII, and existing URLs must keep resolving.

Third-party code lives under `vendor/` as exact copies of upstream releases (see `vendor/README.md`); `vendor/slugify` was bumped to 2.0.0 last week.

Node 24, `npm test`.
